// Compute the minimum element of a non-empty array of integers.
fn minimum(a: Vec<i32>) -> i32 {
    assert!(!a.is_empty(), "input array must be non-empty");

    let mut m = a[0];
    for &x in a.iter().skip(1) {
        if x < m {
            m = x;
        }
    }
    m
}

